class Solution {
public:
    std::string smallestNumber(std::string pattern) {
        std::string ans = "";
        std::vector<char> stk;
        for (int i = 0; i <= (int)pattern.size(); ++i) {
            stk.push_back('1' + i);
            if (i == (int)pattern.size() || pattern[i] == 'I') {
                while (!stk.empty()) {
                    ans += stk.back();
                    stk.pop_back();
                }
            }
        }
        return ans;
    }
};

class Solution {
    public String smallestNumber(String pattern) {
        StringBuilder sb = new StringBuilder();
        java.util.Stack<Integer> stk = new java.util.Stack<>();
        for (int i = 0; i <= pattern.length(); ++i) {
            stk.push(i + 1);
            if (i == pattern.length() || pattern.charAt(i) == 'I') {
                while (!stk.isEmpty()) {
                    sb.append(stk.pop());
                }
            }
        }
        return sb.toString();
    }
}

var smallestNumber = function(pattern) {
    const ans = [];
    const stk = [];
    for (let i = 0; i <= pattern.length; ++i) {
        stk.push(i + 1);
        if (i === pattern.length || pattern[i] === 'I') {
            while (stk.length) {
                ans.push(stk.pop());
            }
        }
    }
    return ans.join('');
};
